#!/usr/bin/env bash
# Scaffolds the Software Factory in the current (dedicated factory) directory.
# GENERATED by make-setup-script.sh from the live factory files: do not edit by hand.
# Existing files are skipped unless --force is passed.
set -euo pipefail

FORCE=false
[ "${1:-}" = "--force" ] && FORCE=true

write_file() {
  local dest="$1" content
  content=$(cat; echo x); content="${content%x}"
  if [ -e "$dest" ] && ! $FORCE; then
    echo "skip   $dest (exists; use --force to overwrite)"
    return
  fi
  mkdir -p "$(dirname "$dest")"
  printf '%s' "$content" > "$dest"
  echo "write  $dest"
}

echo "Scaffolding 6-Agent Claude Code Software Factory..."

write_file '.mcp.json' <<'FACTORY_EOF'
{
  "mcpServers": {
    "atlassian": {
      "type": "http",
      "url": "https://mcp.atlassian.com/v1/mcp"
    }
  }
}
FACTORY_EOF

write_file '.gitignore' <<'FACTORY_EOF'
# Per-machine factory settings (target repo, sandbox paths).
.claude/settings.local.json
.DS_Store
FACTORY_EOF

